@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ── View transitions ──────────────────────────────────────────────── */

/* Directional page slides. The layout-level <ViewTransition> tags its
   snapshots with these classes based on the navigation's transition type
   (see TransitionLink / app/layout.tsx). */
::view-transition-old(*.page-slide-forward) {
  animation: 250ms cubic-bezier(0.4, 0, 0.2, 1) both page-slide-out-to-left;
}

::view-transition-new(*.page-slide-forward) {
  animation: 250ms cubic-bezier(0.4, 0, 0.2, 1) both page-slide-in-from-right;
}

::view-transition-old(*.page-slide-back) {
  animation: 250ms cubic-bezier(0.4, 0, 0.2, 1) both page-slide-out-to-right;
}

::view-transition-new(*.page-slide-back) {
  animation: 250ms cubic-bezier(0.4, 0, 0.2, 1) both page-slide-in-from-left;
}

/* Fallback for untyped navigations (e.g. browser back/forward). */
::view-transition-old(*.page-cross-fade) {
  animation: 200ms ease both page-fade-out;
}

::view-transition-new(*.page-cross-fade) {
  animation: 200ms ease both page-fade-in;
}

/* Suspense reveals: cross-fade the skeleton out and the content in. */
::view-transition-old(*.suspense-fade) {
  animation: 250ms ease both page-fade-out;
}

::view-transition-new(*.suspense-fade) {
  animation: 250ms ease both page-fade-in;
}

/* Shared-element morph (grid thumbnail ↔ detail hero). The browser animates
   the group's position/size automatically; just tune its timing. */
::view-transition-group(*) {
  animation-duration: 300ms;
  animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
}

@keyframes page-slide-out-to-left {
  to {
    transform: translateX(-48px);
    opacity: 0;
  }
}

@keyframes page-slide-in-from-right {
  from {
    transform: translateX(48px);
    opacity: 0;
  }
}

@keyframes page-slide-out-to-right {
  to {
    transform: translateX(48px);
    opacity: 0;
  }
}

@keyframes page-slide-in-from-left {
  from {
    transform: translateX(-48px);
    opacity: 0;
  }
}

@keyframes page-fade-out {
  to {
    opacity: 0;
  }
}

@keyframes page-fade-in {
  from {
    opacity: 0;
  }
}

/* ── Reduced motion ────────────────────────────────────────────────── */

/* Disable every view-transition animation (updates apply instantly) and
   stop the skeleton pulse when the user prefers reduced motion. */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-image-pair(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none !important;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

